#include "symrep_bootstrap.hpp"
#include <unordered_map>
using namespace symrep;using Word=uint64_t;
static Word code(const std::vector<size_t>& w){Word z=0;for(auto a:w)z=88*z+a;return z;}
struct Dual{std::vector<std::vector<size_t>> words;std::vector<Q> scales;};
static Dual dual(const fs::path& path,size_t w){std::ifstream in(path);size_t n,k;in>>n>>k;require(k==w,"dual weight");Dual d;for(size_t r=0;r<n;++r){std::vector<size_t> q(w);for(auto& a:q){in>>a;require(a>0&&a<=88,"dense88 index");--a;}std::string x;in>>x;require(bool(in),"dual parse");d.words.push_back(q);d.scales.push_back(Q(x));require(d.scales.back()!=0,"zero scale");}return d;}
static Q entry(const Vec& v,size_t c){for(auto[j,x]:v){if(size_t(j)==c)return x;if(size_t(j)>c)break;}return Q(0);}
int main(int argc,char**argv){try{require(argc==3,"usage dual_origin_audit OUT BOOT");fs::path out=argv[1],boot=argv[2];auto start=std::chrono::steady_clock::now();Dual prev;prev.words={{}};prev.scales={Q(1)};size_t scans=0,chartrows=0;
 for(size_t w=1;w<=6;++w){auto d=dual(out/("dual_audit_w"+std::to_string(w)+".txt"),w);std::unordered_map<Word,size_t> old;for(size_t i=0;i<prev.words.size();++i)require(old.emplace(code(prev.words[i]),i).second,"duplicate previous word");std::vector<size_t> owner(88*prev.words.size(),SIZE_MAX),which(d.words.size()),seen(d.words.size());std::unordered_set<Word> unique;
 for(size_t r=0;r<d.words.size();++r){auto q=d.words[r];require(unique.insert(code(q)).second,"duplicate dual word");size_t last=q.back();q.pop_back();auto it=old.find(code(q));require(it!=old.end(),"nonchronological prefix");size_t c=88*it->second+last;require(owner[c]==SIZE_MAX,"duplicate selected recurrence column");owner[c]=r;which[r]=it->second;}
 size_t nnz=0;{
 using namespace WXF_PARSER;using namespace SparseRREF::wxf_checked;
 auto bytes=file_to_ustr(out/("FEC_"+std::to_string(w)+".wxf"));Parser parser(bytes);size_t position=0,value=0;int rational=0;int_t numerator;std::vector<size_t> rp;std::unordered_map<size_t,size_t> selected;
 auto iv=[&](const Token&t){exact_integer(t);return integer(t)?int_t(t.get_integer()):int_t(std::string(t.get_string_view()).c_str());};
 auto accept=[&](const Q&x){auto it=selected.find(value);if(it!=selected.end()){size_t r=it->second;require(x*prev.scales[which[r]]==d.scales[r],"streaming recursive dual scale mismatch");++seen[r];}++value;};
 parser.parse_each([&](Token&&token){size_t p=position++;if(p==3){integer_array(token,1);require(token.dimensions[1]==3&&natural(token,0)==d.words.size()&&natural(token,1)==prev.words.size()&&natural(token,2)==88,"streaming chart shape");}
 else if(p==10){integer_array(token,1);for(size_t r=0;r<=d.words.size();++r)rp.push_back(natural(token,r));nnz=rp.back();}
 else if(p==11){integer_array(token,2);require(token.dim(0)==nnz&&token.dim(1)==2,"streaming index shape");size_t row=0;for(size_t k=0;k<nnz;++k){while(k>=rp[row+1])++row;size_t c=88*(natural(token,2*k)-1)+natural(token,2*k+1)-1;require(c<owner.size(),"streaming column bounds");auto r=owner[c];if(r!=SIZE_MAX){require(r==row,"private column appears in another row");selected.emplace(k,r);}}}
 else if(p>=14){if(rational==1){require(token.type==WXF_HEAD::symbol&&token.get_string_view()=="Rational","rational symbol");rational=2;}else if(rational==2){numerator=iv(token);rational=3;}else if(rational==3){auto den=iv(token);require(den!=0,"denominator");accept(Q(numerator,den));rational=0;}else if(token.type==WXF_HEAD::func){require(token.length==2,"rational length");rational=1;}else accept(Q(iv(token)));}});
 require(value==nnz&&rational==0,"streaming value count");}
 for(auto n:seen)require(n==1,"dual column absent or duplicated");scans+=nnz;chartrows+=d.words.size();std::cout<<"CHART weight="<<w<<" rows="<<d.words.size()<<" scanned="<<nnz<<" exact_isolation=pass seconds="<<seconds(start)<<std::endl;prev=std::move(d);
 }
 std::vector<std::pair<std::vector<size_t>,Q>> sample;{auto f=read(boot/"steinmann/affine/reconstructed_w6_embedded.wxf");require(f.rank()==6,"word rank");size_t step=std::max(size_t(1),f.nnz()/120),n=0;for(size_t i=0;i<f.dim(0);++i)for(size_t p=f.rowptr()[i];p<f.rowptr()[i+1];++p)if(n++%step==0){std::vector<size_t> w{i};auto idx=f.index(p);for(size_t j=0;j<5;++j)w.push_back(idx[j]);sample.emplace_back(w,f.val(p));}}
 std::vector<std::vector<Mat>> trans;for(size_t w=1;w<=5;++w){auto p=w==1?boot/"data/FEC_1.wxf":boot/("steinmann/FEC_"+std::to_string(w)+".wxf");auto t=read(p);std::vector<Mat> by;for(size_t a=0;a<88;++a)by.emplace_back(t.dim(1),t.dim(0));for(size_t r=0;r<t.dim(0);++r)for(size_t p=t.rowptr()[r];p<t.rowptr()[r+1];++p){auto idx=t.index(p);by[idx[1]][idx[0]].push_back(index(r),t.val(p));}trans.push_back(std::move(by));}
 std::vector<Vec> last(88);{auto f=read(boot/"steinmann/affine/final_compact_w6.wxf");require(f.rank()==3&&f.dim(0)==1,"compact source shape");for(size_t p=0;p<f.nnz();++p){auto idx=f.index(p);last[idx[1]].push_back(idx[0],f.val(p));}for(auto&v:last)normalize(v);}
 std::unordered_map<Word,Q> cache;auto coeff=[&](const std::vector<size_t>&w)->Q{auto c=code(w);auto it=cache.find(c);if(it!=cache.end())return it->second;Vec v;v.push_back(0,Q(1));for(size_t k=0;k<5;++k)v=mul(v,trans[k][w[k]]);Q x(0);for(auto[j,a]:v)x+=a*entry(last[w.back()],j);cache.emplace(c,x);return x;};size_t alg=0;for(auto&[w,x]:sample){require(coeff(w)==x,"compact recursive actual-word coefficient mismatch");if(*std::max_element(w.begin(),w.end())>=64)++alg;}std::cout<<"WORDS samples="<<sample.size()<<" algebraic_dense_samples="<<alg<<" recursive_lookup=pass seconds="<<seconds(start)<<std::endl;
 auto o=read_matrix(out/"affine_tail_w8_TF175_origin.wxf"),E=read_matrix(out/"lastpair_E.wxf");std::ifstream cfg(out/"affine_tail_static.txt");size_t n,tmp;cfg>>n;for(size_t i=0;i<n;++i)cfg>>tmp;cfg>>n;Mat P(88,76);for(size_t i=0;i<n;++i){size_t a,b;std::string x;cfg>>a>>b>>x;P[a-1].push_back(index(b-1),Q(x));}for(auto&v:P.rows)normalize(v);require(bool(cfg),"P parse");size_t checked=0,repeated=0,nz=0;for(auto&r:o.rows)if(r.nnz())++nz;size_t step=std::max(size_t(1),nz/50),ix=0;
 for(size_t r=0;r<o.nrow;++r)if(o[r].nnz()&&ix++%step==0){auto full=mul(o[r],E);require(full.nnz()>0,"origin maps to zero unexpectedly");std::vector<size_t> pick{0,full.nnz()/2,full.nnz()-1};for(auto k:pick){size_t c=full(k),t=c/76,a=c%76;auto word=prev.words[r];word.push_back(t);Q actual(0);std::unordered_set<Word> deletion;for(size_t p=0;p<7;++p){Q l=entry(P[word[p]],a);if(l!=0){auto shorter=word;shorter.erase(shorter.begin()+p);if(!deletion.insert(code(shorter)).second)++repeated;actual+=l*coeff(shorter);}}actual/=prev.scales[r];require(actual==full[k],"independent seven-position shuffle coefficient mismatch");++checked;}}
 std::ofstream j(out/"dual_origin_independent_audit.json");j<<"{\"all_checks_pass\":true,\"complete_private_chart_weights\":[1,2,3,4,5,6],\"private_chart_rows_checked\":"<<chartrows<<",\"recurrence_coefficients_scanned\":"<<scans<<",\"recursive_F3_actual_word_samples\":"<<sample.size()<<",\"samples_including_algebraic_dense_indices\":"<<alg<<",\"affine_origin_exact_seven_position_shuffle_checks\":"<<checked<<",\"repeated_deletion_words_counted_with_multiplicity\":"<<repeated<<",\"recursive_coefficient_cache_entries\":"<<cache.size()<<",\"alphabet\":\"dense retained88 one-based in files; zero-based only internally\",\"coordinate_proof\":\"At each level a selected recurrence column (previous basis row,last letter) occurs in exactly one current row. The chronological actual word formed from the previously private word and last letter therefore isolates that row, with product diagonal scale. Full recurrence scans certify every saved selected column through weight6.\",\"shuffle_proof\":\"The coefficient of F3 shuffle a weight1 letter in the seven-letter word(q,t) is the sum over all seven deletion positions, including identical deletions separately; divide by the private prefix scale exactly once.\",\"scope\":\"Full dual-chart isolation; sampled independent compact-vs-word F3 and sampled affine-source coefficients. The producer separately verifies every local6688-component tail residual. No F4 target read; global sewing remains pending.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"PASS origin_samples="<<checked<<" repeated="<<repeated<<" seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
